changeSet.sql:
CREATE TABLE merchants ( account_code VARCHAR(128) PRIMARY KEY, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', currency CHAR(3) NOT NULL, is_auto_captured BOOLEAN NOT NULL, is_auto_settled BOOLEAN NOT NULL, platform_fee_fixed BIGINT NOT NULL, platform_fee_bps INTEGER NOT NULL, profile JSONB NOT NULL, created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'), updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'), CONSTRAINT chk_merchants_status CHECK (status IN ('ACTIVE', 'SUSPENDED', 'CLOSED')), CONSTRAINT chk_merchants_currency CHECK (currency ~ '^[A-Z]{3}$'), CONSTRAINT chk_merchants_fee CHECK (platform_fee_fixed >= 0 AND platform_fee_bps BETWEEN 0 AND 10000) );
CREATE TABLE sellers ( account_code VARCHAR(128) PRIMARY KEY, merchant_code VARCHAR(128) NOT NULL REFERENCES merchants (account_code), status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'), updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'), CONSTRAINT chk_sellers_status CHECK (status IN ('ACTIVE', 'SUSPENDED', 'CLOSED')) ); -- a merchant's sellers CREATE INDEX idx_sellers_merchant ON sellers (merchant_code);
CREATE TABLE ledger_accounts ( account_code VARCHAR(128) PRIMARY KEY, ledger_type VARCHAR(64) NOT NULL, owner_code VARCHAR(128) NOT NULL, seller_code VARCHAR(128) REFERENCES sellers (account_code), currency CHAR(3) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'), updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'), CONSTRAINT chk_ledger_accounts_status CHECK (status IN ('ACTIVE', 'SUSPENDED', 'CLOSED')), CONSTRAINT chk_ledger_accounts_currency CHECK (currency ~ '^[A-Z]{3}$') ); -- ledger lookups: a merchant's (or the platform's) accounts, a seller's accounts CREATE INDEX idx_ledger_accounts_owner ON ledger_accounts (owner_code); CREATE INDEX idx_ledger_accounts_seller ON ledger_accounts (seller_code); -- natural order for account codes (ORDER BY ... COLLATE natural_order): digit runs compare as numbers, -- so SELLER-5-2 comes before SELLER-5-10. ICU with numeric ordering (kn). CREATE COLLATION natural_order (provider = icu, locale = 'und-u-kn-true');
-- The platform's own ledger accounts, per supported currency. They are ours, not a merchant's, so -- account onboarding does not create them; a new currency is a new row set here. INSERT INTO ledger_accounts (account_code, ledger_type, owner_code, currency) VALUES ('PLATFORM_CASH.GLOBAL.EUR', 'PLATFORM_CASH', 'GLOBAL', 'EUR'), ('PSP_RECEIVABLE.GLOBAL.EUR', 'PSP_RECEIVABLE', 'GLOBAL', 'EUR'), ('PLATFORM_REVENUE.GLOBAL.EUR', 'PLATFORM_REVENUE', 'GLOBAL', 'EUR'), ('PSP_FEE_EXPENSE.GLOBAL.EUR', 'PSP_FEE_EXPENSE', 'GLOBAL', 'EUR');
